solutionCode:
export function juntarCaminho(partes) {
  const limpos = [];
  for (const parte of partes) {
    const limpa = String(parte).replace(/^\/+/g, '').replace(/\/+$/g, '');
    if (limpa !== '') {
      limpos.push(limpa);
    }
  }
  return limpos.join('/');
}

export function contarLinhas(texto) {
  if (texto === '' || texto === undefined || texto === null) {
    return 0;
  }
  return texto.split('\n').length;
}
